  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

// HTTPS enforcement (use in production)
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync(process.env.SSL_KEY_PATH), // Read from environment
  cert: fs.readFileSync(process.env.SSL_CERT_PATH), // Read from environment
};

